using Microsoft.EntityFrameworkCore;
class AppDbContext : DbContext
{
    public DbSet<Order> Orders => Set<Order>();
    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        // EF Core 9 breaking change: HasData() no longer accepts expressions
        // like DateTime.UtcNow that are evaluated at migration-generation time.
        // Use a fixed value instead to ensure deterministic seed data.
        modelBuilder.Entity<Order>().HasData(
            new Order { Id = 1, CreatedAt = new DateTime(2024, 1, 1, 0, 0, 0, DateTimeKind.Utc) });
    }
}
class Order { public int Id { get; set; } public DateTime CreatedAt { get; set; } }

// --- Cosmos DB context demonstrating EF Core 9 breaking changes ---

class CosmosDbContext : DbContext
{
    public DbSet<Product> Products => Set<Product>();

    protected override void OnConfiguring(DbContextOptionsBuilder options)
        => options.UseCosmos(
            "AccountEndpoint=https://localhost:8081/;AccountKey=dummy",
            "ShopDb");

    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        // Breaking Change #1: EF Core 9 Cosmos provider now uses "$type"
        // instead of "Discriminator" for the discriminator property by default.
        // For existing documents that already store "Discriminator", explicitly
        // configure the property name to maintain backward compatibility.
        modelBuilder.Entity<Product>()
            .HasDiscriminator<string>("Discriminator")
            .HasValue<Product>("Product")
            .HasValue<DiscountedProduct>("DiscountedProduct");

        modelBuilder.Entity<Product>().ToContainer("Products");
        modelBuilder.Entity<Product>().HasPartitionKey(p => p.Category);
    }
}

class Product
{
    public string Id { get; set; } = default!;
    public string Name { get; set; } = default!;
    public string Category { get; set; } = default!;
}

class DiscountedProduct : Product
{
    public decimal Discount { get; set; }
}

// Breaking Change #2: EF Core 9 Cosmos provider removed synchronous I/O.
// All queries/saves must use async methods (ToListAsync, SaveChangesAsync, etc.)
class ProductService
{
    private readonly CosmosDbContext _db;
    public ProductService(CosmosDbContext db) => _db = db;

    // BEFORE (EF Core 8 - synchronous, no longer supported):
    //   var products = _db.Products.Where(p => p.Category == cat).ToList();
    //   _db.SaveChanges();

    // AFTER (EF Core 9 - async required):
    public async Task<List<Product>> GetByCategoryAsync(string cat)
        => await _db.Products.Where(p => p.Category == cat).ToListAsync();

    public async Task AddProductAsync(Product product)
    {
        _db.Products.Add(product);
        await _db.SaveChangesAsync();
    }
}

