arguments.new_str:
using Microsoft.EntityFrameworkCore;
class MigrationRunner
{
    // Breaking Change: EF Core 9 throws if Migrate() is called inside an
    // explicit transaction. Migrations manage their own transactions internally.
    void ApplyMigrations(AppDbContext db)
    {
        var strategy = db.Database.CreateExecutionStrategy();
        strategy.Execute(() =>
        {
            // Removed BeginTransaction/Commit wrapping Migrate() — EF Core 9
            // no longer allows this and will throw InvalidOperationException.
            db.Database.Migrate();
        });
    }
}

